 'approved','original_iclub',true,encode(digest(convert_to('Ma’lum son elektron chiqarilgandan keyingi juda katta sakrash navbatdagi elektron ichki qavatdan olinayotganini bildiradi. Ikkinchi va uchinchi ionlanish energiyalari orasidagi katta sakrash ikki valent elektronni ko‘rsatadi, bu magniy kabi 2-guruh elementiga xos.','UTF8'),'sha256'),'hex'),now(),now())
